import '../models/models.dart';import '../models/quick_entry_draft.dart';
class QuickEntryParser{QuickEntryDraft parse(String raw,List<Equipment> equipment,{DateTime? now}){final n=now??DateTime.now(),low=raw.toLowerCase(),tag=_tag(raw,equipment);EquipmentState? state;if(low.contains('tag out')||low.contains('tagout')||low.contains('απομόν')){state=EquipmentState.taggedOut;}else if(low.contains('stopped')||low.contains('stop')||low.contains('εκτός')){state=EquipmentState.outOfService;}else if(low.contains('standby')||low.contains('εφεδρ')){state=EquipmentState.standby;}else if(low.contains('running')||low.contains('started')||low.contains('σε λειτουργ')){state=EquipmentState.running;}
  else if((low.contains('under maintenance')||low.contains('in maintenance')||low.contains('σε συντήρ'))&&!low.contains('informed')&&!low.contains('ενημερ')){state=EquipmentState.maintenance;}final informed=low.contains('informed')||low.contains('ενημερ');final reminder=_time(raw,n)??_relative(raw,n);final needsCheck=low.contains('check')||low.contains('recheck')||low.contains('έλεγχ')||low.contains('ξανά');final watch=low.contains('monitor')||low.contains('watch')||low.contains('παρακολ');return QuickEntryDraft(raw:raw.trim(),tag:tag,equipmentState:state,maintenanceInformed:informed,actionText:needsCheck?'Follow up: ${raw.trim()}':null,reminderAt:reminder,watchText:watch?raw.trim():null,warnings:[if(tag==null)'No equipment TAG matched',if(state==EquipmentState.taggedOut)'App TAG OUT is a recorded operator status only; verify formal LOTO/PTW independently.']);}
DateTime? _relative(String raw,DateTime now){final low=raw.toLowerCase();final m=RegExp(r'(?:in|σε)\s+(\d+)\s*(min|mins|minutes|λεπτ|λεπτά|hour|hours|hr|hrs|ώρα|ώρες)').firstMatch(low);if(m==null){return null;}final v=int.tryParse(m.group(1)!)??0,unit=m.group(2)!;final hours=unit.startsWith('hour')||unit.startsWith('hr')||unit.startsWith('ώρα')||unit.startsWith('ώρ');return now.add(Duration(minutes:hours?v*60:v));}
 String? _tag(String raw,List<Equipment> equipment){final x=raw.toUpperCase().replaceAll(RegExp(r'[^A-Z0-9]'),'');for(final e in equipment){if(x.contains(e.tag.toUpperCase().replaceAll(RegExp(r'[^A-Z0-9]'),''))){return e.tag;}}return null;}
DateTime? _time(String raw,DateTime now){final m=RegExp(r'\b([01]?\d|2[0-3])[:.]([0-5]\d)\b').firstMatch(raw);if(m==null)return null;var d=DateTime(now.year,now.month,now.day,int.parse(m.group(1)!),int.parse(m.group(2)!));if(d.isBefore(now)){d=d.add(const Duration(days:1));}return d;}}
